const questions=[['Dolgozhatok Magyarországon ukrán állampolgárként?','Igen, megfelelő tartózkodási és munkavállalási jogosultság esetén. A pontos feltételek a jelenlegi státuszodtól és az egyéni körülményeidtől függenek.'],['Ha Lengyelországban vagy Csehországban dolgozom, átköltözhetek Magyarországra?','Lehetséges, de a másik országban kiadott tartózkodási vagy munkavállalási engedély nem biztosít automatikusan magyarországi munkavállalási jogosultságot. Munkatársunk tájékoztat a jelentkezés feltételeiről.'],['Mi történik, ha katonai kötelezettség alá tartozom?','A magyarországi lehetőségeidet az aktuális jogszabályok és az egyéni helyzeted alapján kell megvizsgálni. A szükséges dokumentumokról és a jelentkezés feltételeiről kérj egyéni tájékoztatást.'],['Beszélnem kell magyarul?','A nyelvi követelmények munkakörönként eltérhetnek. Jelentkezéskor egyeztetjük, milyen nyelvtudás szükséges.'],['Van szálláslehetőség?','Az elérhető szálláslehetőségekről és azok feltételeiről munkatársunk tud tájékoztatást adni.']];
const list=document.querySelector('#faq-list');questions.forEach(([q,a])=>{const d=document.createElement('details');const s=document.createElement('summary');s.append(document.createTextNode(q));const plus=document.createElement('span');plus.textContent='+';plus.setAttribute('aria-hidden','true');s.append(plus);const p=document.createElement('p');p.textContent=a;d.append(s,p);list.append(d)});
const select=document.querySelector('#position');function update(){document.querySelector('#selection-note').textContent=select.value?'Az állásportálon erre keress: '+select.value+'.':'Az állásportálon keress a településre vagy a munkakörre.'}document.querySelectorAll('.choose').forEach(a=>a.addEventListener('click',()=>{select.value=a.dataset.job;update()}));select.addEventListener('change',update);
